"""Covering numbers and the box-counting dimension of a truth set."""
from __future__ import annotations
import math
from typing import Callable, List

FreePredicate = Callable[[int], bool]

def admissible_prefix_count(free: FreePredicate, n: int) -> int:
    """A_n = 2^(number of free coordinates below n)."""
    return 2 ** sum(1 for i in range(n) if free(i))

def dimension_estimate(free: FreePredicate, n: int) -> float:
    """Finite estimate log2(A_n)/n at resolution 2^-n."""
    return math.log2(admissible_prefix_count(free, n)) / n if n else 0.0

def parity_free(i: int) -> bool:
    return i % 2 == 0

if __name__ == "__main__":
    depths: List[int] = [4, 16, 64, 256, 1024]
    for n in depths:
        print(f"n={n:>5}  A_n={admissible_prefix_count(parity_free, n):>40}  "
              f"dim~={dimension_estimate(parity_free, n):.6f}")
    print("dim_B(parity truth set) = 0.5")

"""Two one-sided approximations: Omega from below, dimension from above."""
from __future__ import annotations
import math
from typing import Callable, List

def toy_halting(program: int, steps: int) -> bool:
    """Decidable stand-in for a universal machine (illustrative only)."""
    return steps >= (program * 2654435761) % 97 + 1

def omega_lower_bounds(num_programs: int, budgets: List[int]) -> List[float]:
    out: List[float] = []
    for b in budgets:
        out.append(sum(2.0 ** (-(p + 1))
                       for p in range(num_programs) if toy_halting(p, b)))
    return out

def dim_estimate(free: Callable[[int], bool], n: int) -> float:
    return sum(1 for i in range(n) if free(i)) / n

if __name__ == "__main__":
    print("Omega lower bounds (from below):",
          [round(x, 4) for x in omega_lower_bounds(64, [1, 10, 50, 200])])
    print("Parity dim upper estimates (from above):",
          [round(dim_estimate(lambda i: i % 2 == 0, n), 4)
           for n in [8, 64, 512]])

